import {effectiveTracks,qualityMatches} from './evidence.js?v=0.6.0';
import {placementOf,placementSummary,rankMatches} from './placement.js?v=0.6.0';
export let CONFIG={currentCycle:'2026-2027',historyYears:[2023,2024,2025,2026]};
export function configure(config){if(!/^20\d{2}-20\d{2}$/.test(config.currentCycle)||!Array.isArray(config.historyYears)||!config.historyYears.every(Number.isInteger))throw new Error('Invalid archive configuration');CONFIG=config}
export const REGIONS={US:'美国',CA:'加拿大',HK:'香港',SG:'新加坡',CN:'中国大陆',TW:'台湾',MO:'澳门',JP:'日本',FR:'法国',DE:'德国',ES:'西班牙',IT:'意大利',VN:'越南',UY:'乌拉圭',IR:'伊朗',UK:'英国',EU:'欧洲',AU:'澳大利亚',KR:'韩国',IL:'以色列',IN:'印度',KW:'科威特',PT:'葡萄牙',NZ:'新西兰',RU:'俄罗斯',OTHER:'其他地区',UNKNOWN:'未核验'};
export const JOBS={faculty:'教职 · 轨道未核验',tt:'终身轨教职',non_tt:'非终身轨教职',postdoc:'博士后',industry:'企业',government:'政府 / 公共机构',research:'研究机构',other:'业界及其他',deferred:'延期',unknown:'岗位类别未核验',on_market:'当季求职中'};
export const BG={all:'全部背景',cn_national:'中国公民 · 公开确认',cn_heritage:'华裔 · 本人公开自述',ug_cn:'本科在中国大陆',ug_hk:'本科在香港',ug_tw:'本科在台湾',ug_other:'本科在其他地区',ug_unknown:'本科地区未核验'};
export const JOB_COLORS={faculty:'#208b78',tt:'#165c4f',non_tt:'#8eb9ac',postdoc:'#8a94ce',industry:'#d49d56',government:'#617c94',research:'#afbcc4',unknown:'#dfe4e8',on_market:'#829ea0'};
export function backgroundMatches(r,bg){const u=r.undergraduate?.region;if(bg==='all')return true;if(bg==='cn_national')return r.identity?.chinese_national?.value==='yes';if(bg==='cn_heritage')return r.identity?.chinese_heritage?.value==='yes';if(bg==='ug_unknown')return !u||u==='UNKNOWN';if(bg==='ug_other')return !!u&&!['CN','HK','TW','UNKNOWN'].includes(u);return u===({ug_cn:'CN',ug_hk:'HK',ug_tw:'TW'}[bg]);}
export function needsOutcomeReview(r){return r.status==='outcome_unknown'||r.status==='placed'&&!r.placement_year}
export function inArchiveCohort(r){return r.status!=='on_market'&&r.market_cycle!==CONFIG.currentCycle&&[r.source_cohort_year,r.graduation_year,r.placement_year].some(y=>CONFIG.historyYears.includes(y))}
export function filterRecords(records,f={}){const words=(f.q||'').toLowerCase().trim().split(/\s+/).filter(Boolean);return records.filter(r=>{const outcome=placementOf(r,f.basis),tracks=effectiveTracks(r,f.researchMode);if(!qualityMatches(r,f.quality))return false;if(!rankMatches(r,f.rank))return false;if(f.material==='jmp'&&!r.jmp)return false;if(f.material==='homepage'&&!r.homepage)return false;if(f.material==='cv'&&!r.cv_url)return false;if(f.scope==='target'&&!r.target_scope)return false;if(f.scope==='extension'&&r.target_scope)return false;if(f.period==='cohorts'&&!inArchiveCohort(r))return false;if(f.period==='unresolved'&&!needsOutcomeReview(r))return false;if(f.period==='current'&&r.market_cycle!==CONFIG.currentCycle)return false;if(f.period==='history'&&!(r.status==='placed'&&CONFIG.historyYears.includes(r.placement_year)&&r.market_cycle!==CONFIG.currentCycle))return false;if(/^20\d{2}$/.test(f.period||'')&&!(r.status==='placed'&&r.placement_year===Number(f.period)))return false;if(f.track==='marketing_unclassified'&&!(tracks.includes('marketing')&&!tracks.some(t=>['qm','cb','strategy'].includes(t))))return false;if(f.track&& !['all','marketing_unclassified'].includes(f.track)&&!tracks.includes(f.track))return false;if(f.origin&&f.origin!=='all'&&r.origin!==f.origin)return false;if(f.school&&f.school!=='all'&&r.school!==f.school)return false;if(f.job&&f.job!=='all'&&outcome.category!==f.job)return false;if(f.destination&&f.destination!=='all'&&outcome.destination_region!==f.destination)return false;if(f.topic&&f.topic!=='all'&&!r.topics.includes(f.topic))return false;if(f.method&&f.method!=='all'&&!r.methods.includes(f.method))return false;if(f.background&&!backgroundMatches(r,f.background))return false;const text=[r.name,r.school,r.program,r.destination,r.source_reported_placement,...(r.subsequent||[]).map(s=>s.institution||s.employer||s.destination),r.role,r.final_placement?.destination,r.final_placement?.role,r.jmp,...(r.aliases||[]),...r.fields,...r.topics,...r.methods].filter(Boolean).join(' ').toLowerCase();return words.every(w=>text.includes(w))})}
export function summarize(records,basis='final'){const outcomes=placementSummary(records,basis);return {count:records.length,schools:new Set(records.map(r=>r.school)).size,historical:records.filter(r=>['placed','outcome_unknown','deferred'].includes(r.status)).length,...outcomes,onMarket:records.filter(r=>r.status==='on_market'&&r.market_cycle===CONFIG.currentCycle).length,identityKnown:records.filter(r=>r.identity?.chinese_national?.value==='yes'||r.identity?.chinese_heritage?.value==='yes').length}}
export function tally(records,fn){const m=new Map();for(const r of records){const values=fn(r);for(const k of new Set(Array.isArray(values)?values:[values]))if(k)m.set(k,(m.get(k)||0)+1)}return [...m].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))}
export function csvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}
